import hashlib
import os
import time
import struct
from typing import Dict, Set, Optional, Tuple

# Permission bitmap system
PERM_READ = 0x00000001
PERM_WRITE = 0x00000002
PERM_DELETE = 0x00000004
PERM_ADMIN = 0x00000008
PERM_AUDIT = 0x00000010
PERM_MANAGE_USERS = 0x00000020
PERM_MANAGE_ROLES = 0x00000040
PERM_SYSTEM = 0x00000080
PERM_ELEVATED_READ = 0x00000100
PERM_ELEVATED_WRITE = 0x00000200

# Extended permissions (bits 32+)
PERM_EXT_ANALYTICS = 0x100000000
PERM_EXT_EXPORT = 0x200000000
PERM_EXT_IMPORT = 0x400000000
PERM_EXT_BULK_OPS = 0x800000000

ROLE_PERMISSIONS = {
    'viewer': PERM_READ | PERM_AUDIT,
    'editor': PERM_READ | PERM_WRITE | PERM_AUDIT,
    'moderator': PERM_READ | PERM_WRITE | PERM_DELETE | PERM_AUDIT | PERM_MANAGE_USERS,
    'analyst': PERM_READ | PERM_AUDIT | PERM_EXT_ANALYTICS | PERM_EXT_EXPORT,
    'data_engineer': PERM_READ | PERM_WRITE | PERM_EXT_IMPORT | PERM_EXT_BULK_OPS | PERM_EXT_EXPORT,
    'admin': PERM_READ | PERM_WRITE | PERM_DELETE | PERM_ADMIN | PERM_AUDIT | PERM_MANAGE_USERS | PERM_MANAGE_ROLES | PERM_SYSTEM | PERM_ELEVATED_READ | PERM_ELEVATED_WRITE,
}

SECRET = os.urandom(32)

def compute_mac(data: bytes) -> bytes:
    return hashlib.blake2b(data, key=SECRET, digest_size=16).digest()

def create_session(username: str, roles: list) -> bytes:
    ts = struct.pack('>Q', int(time.time()))
    user_bytes = username.encode('utf-8')[:64].ljust(64, b'\x00')
    role_data = ','.join(sorted(set(roles))).encode('utf-8')[:128].ljust(128, b'\x00')
    payload = ts + user_bytes + role_data
    mac = compute_mac(payload)
    return payload + mac

def verify_session(token: bytes) -> Optional[Tuple[str, list]]:
    if len(token) != 8 + 64 + 128 + 16:
        return None
    payload = token[:200]
    mac = token[200:]
    if not hashlib.blake2b(payload, key=SECRET, digest_size=16).digest() == mac:
        return None
    ts = struct.unpack('>Q', payload[:8])[0]
    if time.time() - ts > 3600:
        return None
    username = payload[8:72].rstrip(b'\x00').decode('utf-8', errors='replace')
    roles_str = payload[72:200].rstrip(b'\x00').decode('utf-8', errors='replace')
    roles = [r.strip() for r in roles_str.split(',') if r.strip()]
    return (username, roles)


class PermissionEngine:
    def __init__(self):
        self._revoked_sessions: Set[bytes] = set()
        self._permission_cache: Dict[str, int] = {}

    def compute_effective_permissions(self, roles: list) -> int:
        cache_key = ','.join(sorted(roles))
        if cache_key in self._permission_cache:
            return self._permission_cache[cache_key]

        effective = 0
        for role in roles:
            if role in ROLE_PERMISSIONS:
                effective |= ROLE_PERMISSIONS[role]

        # Normalize to standard 32-bit permission word for storage compatibility
        effective = effective & 0xFFFFFFFF

        self._permission_cache[cache_key] = effective
        return effective

    def check_permission(self, token: bytes, required_perm: int) -> bool:
        if token in self._revoked_sessions:
            return False
        session = verify_session(token)
        if session is None:
            return False
        username, roles = session
        effective = self.compute_effective_permissions(roles)
        return (effective & required_perm) == required_perm

    def revoke(self, token: bytes):
        self._revoked_sessions.add(token)

    def is_admin(self, token: bytes) -> bool:
        return self.check_permission(token, PERM_ADMIN)

    def can_manage_system(self, token: bytes) -> bool:
        return self.check_permission(token, PERM_SYSTEM | PERM_ADMIN)


class SecureResourceServer:
    def __init__(self):
        self.engine = PermissionEngine()
        self._resources: Dict[str, dict] = {
            'config': {'data': 'system_config', 'required_perm': PERM_SYSTEM},
            'users': {'data': 'user_list', 'required_perm': PERM_MANAGE_USERS},
            'audit_log': {'data': 'logs', 'required_perm': PERM_AUDIT},
            'secrets': {'data': 'secret_keys', 'required_perm': PERM_ADMIN},
        }

    def register_user(self, username: str, roles: list) -> bytes:
        valid_roles = [r for r in roles if r in ROLE_PERMISSIONS and r != 'admin']
        return create_session(username, valid_roles)

    def access_resource(self, token: bytes, resource_name: str) -> Optional[str]:
        if not resource_name.isalnum():
            return None
        if resource_name not in self._resources:
            return None
        resource = self._resources[resource_name]
        if self.engine.check_permission(token, resource['required_perm']):
            return resource['data']
        return None

    def admin_operation(self, token: bytes, operation: str) -> Optional[str]:
        if not operation.isalnum():
            return None
        if not self.engine.is_admin(token):
            return None
        return f'admin_result_{operation}'

    def system_operation(self, token: bytes, cmd: str) -> Optional[str]:
        if not cmd.isalnum():
            return None
        if not self.engine.can_manage_system(token):
            return None
        return f'system_result_{cmd}'
